.darma-loader-clock-hands {
  position: relative;
  width: 50px;
  height: 50px;
  border-radius: 50%;
  border: 3px solid var(--loader-color, #6366f1);
  box-sizing: border-box;
}
.darma-loader-clock-hands::before {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  width: 6px;
  height: 6px;
  margin: -3px 0 0 -3px;
  border-radius: 50%;
  background: #4338ca;
  z-index: 2;
}
.darma-loader-clock-hands b, .darma-loader-clock-hands i {
  position: absolute;
  left: 50%;
  bottom: 50%;
  border-radius: 2px;
  transform-origin: bottom center;
}
.darma-loader-clock-hands b {
  width: 3px;
  height: 12px;
  margin-left: -1.5px;
  background: #4338ca;
  animation: darma-loader-clock-hands-spin 6s linear infinite;
}
.darma-loader-clock-hands i {
  width: 2px;
  height: 18px;
  margin-left: -1px;
  background: var(--loader-color, #6366f1);
  animation: darma-loader-clock-hands-spin 2s linear infinite;
}
@keyframes darma-loader-clock-hands-spin { to { transform: rotate(360deg); } }

